#!/usr/bin/env bash
# Commit the regenerated charts/ and checks/ to a new branch regen/<run id>, push that branch (never the base branch) and
# open a PR with the diff stat and the changed lines of charts/facts.md. If Actions may not create PRs in this repo, print
# the compare URL instead; that does not fail the job. Inputs (env): RUN_ID, BASE_REF, REPO; optional GITHUB_SERVER_URL,
# GITHUB_STEP_SUMMARY, RUNNER_TEMP, CACHE_NOTE, GH_TOKEN (for gh).
set -euo pipefail
: "${RUN_ID:?}" "${BASE_REF:?}" "${REPO:?}"
SERVER="${GITHUB_SERVER_URL:-https://github.com}"
SUMMARY="${GITHUB_STEP_SUMMARY:-/dev/null}"
TMP="${RUNNER_TEMP:-$(mktemp -d)}"
BRANCH="regen/${RUN_ID}"
RUN_URL="$SERVER/$REPO/actions/runs/$RUN_ID"
COMPARE_URL="$SERVER/$REPO/compare/$BASE_REF...$BRANCH?expand=1"

# Anything that changed outside the two output folders is reported, not committed.
others=$(git status --porcelain --untracked-files=all | grep -v -E '^(.. )(charts|checks)/' || true)
git add -A -- charts checks
if git diff --cached --quiet; then
  echo "No output changed: the committed charts already match this data. No branch, no PR." | tee -a "$SUMMARY"
  exit 0
fi

git show "HEAD:charts/facts.md" > "$TMP/facts_before.md" 2>/dev/null || : > "$TMP/facts_before.md"
git show ":charts/facts.md" > "$TMP/facts_after.md" 2>/dev/null || : > "$TMP/facts_after.md"
git diff --cached --stat=120 > "$TMP/stat.txt"
# git diff --no-index, not GNU diff options, so the script also runs on macOS. Changed lines only: "-" before, "+" after.
{ git diff --no-index --no-color --unified=0 "$TMP/facts_before.md" "$TMP/facts_after.md" || true; } | sed -n '/^@@/,$p' | grep -v '^@@' > "$TMP/facts_diff.txt" || true
facts_total=$(wc -l < "$TMP/facts_diff.txt" | tr -d ' ')
cut -c1-700 "$TMP/facts_diff.txt" | head -n 250 > "$TMP/facts_diff_shown.txt"

{
  echo "Regenerated by [workflow run $RUN_ID]($RUN_URL) (\`rebuild.yml\`): extract, verify_opm, build, spot_check and check_literals all passed."
  echo
  echo "Review before merging: the numbers in \`charts/facts.md\` move whenever OPM publishes or revises a file, not only because of code changes."
  [ -n "${CACHE_NOTE:-}" ] && { echo; echo "Extract cache: $CACHE_NOTE"; }
  echo
  echo "## Diff stat"
  echo '```'; cat "$TMP/stat.txt"; echo '```'
  echo
  echo "## charts/facts.md: lines that changed (- before, + after)"
  if [ "$facts_total" = 0 ]; then
    echo "facts.md did not change."
  else
    echo "$facts_total changed lines in all; each line is cut at 700 characters and the list at 250 lines (the full diff is in the branch)."
    echo '```diff'; cat "$TMP/facts_diff_shown.txt"; echo '```'
  fi
  if [ -n "$others" ]; then
    echo
    echo "## Not committed (changed outside charts/ and checks/)"
    echo '```'; echo "$others"; echo '```'
  fi
} > "$TMP/body_full.md"
# GitHub rejects PR bodies over 65536 characters.
head -c 60000 "$TMP/body_full.md" > "$TMP/body.md"
[ "$(wc -c < "$TMP/body_full.md")" -gt 60000 ] && printf '\n\n(body cut at 60000 characters)\n' >> "$TMP/body.md"

git -c user.name="github-actions[bot]" -c user.email="41898282+github-actions[bot]@users.noreply.github.com" \
  commit -q -m "Regenerate charts and checks (workflow run $RUN_ID)"
git push origin "HEAD:refs/heads/$BRANCH"

{
  echo "### Regenerated outputs"
  echo "Branch \`$BRANCH\` pushed. Diff stat:"
  echo '```'; cat "$TMP/stat.txt"; echo '```'
  echo "facts.md: $facts_total changed lines."
} >> "$SUMMARY"

if url=$(gh pr create --repo "$REPO" --base "$BASE_REF" --head "$BRANCH" \
      --title "Regenerate charts ($(date -u +%Y-%m-%d), run $RUN_ID)" --body-file "$TMP/body.md" 2>"$TMP/pr_err.txt"); then
  echo "PR opened: $url" | tee -a "$SUMMARY"
else
  echo "Could not open a PR ($(head -c 300 "$TMP/pr_err.txt" | tr '\n' ' '))." | tee -a "$SUMMARY"
  echo "If this is the repo setting 'Allow GitHub Actions to create and approve pull requests', turn it on or open the PR by hand:" | tee -a "$SUMMARY"
  echo "$COMPARE_URL" | tee -a "$SUMMARY"
fi
exit 0
